<script setup lang="ts">
import { ref } from 'vue'
import AppCard from '../../components/AppCard.vue'
import BottomNav from '../../components/BottomNav.vue'
import PrimaryButton from '../../components/PrimaryButton.vue'
import { healthRepository } from '../../services/mock/repositories'
import { useHealthStore } from '../../stores/health'
import type { HealthReport } from '../../types/domain'
const reports = ref<HealthReport[]>([]); const loading = ref(false); const store = useHealthStore(); const uni = (globalThis as any).uni
const load = async () => { reports.value = await healthRepository.listReports() }; load()
const upload = async () => { loading.value = true; await healthRepository.uploadReport('体检报告_20241010.pdf'); await new Promise(r => setTimeout(r, 600)); loading.value = false; store.markReportUploaded(); await load(); uni.showToast({ title: '解析成功' }) }
const go = () => uni.navigateTo({ url: '/pages/result/index' })
</script>
<template><view class="page"><view class="topbar"><text class="back" @click="uni.navigateBack()">‹</text><text class="top-title">体检报告</text><text>♧</text></view><view class="tabs"><text class="active">上传报告</text><text>历史报告</text></view><AppCard class="upload-card"><view class="upload-box" @click="upload"><text class="upload-icon">⇧</text><text class="upload-title">{{ loading ? '正在解析…' : '上传体检报告' }}</text><text class="muted">支持 PDF · JPG · PNG</text><text class="muted">最大 20MB</text><button class="btn">选择文件</button></view><view v-if="store.state.hasUploadedReport" class="file-item"><view class="file-icon">▤</view><view class="grow"><text>体检报告_20241010.pdf</text><text class="muted">2.3 MB</text></view><text>×</text></view></AppCard><view class="section-title">历史报告</view><AppCard><view v-for="report in reports" :key="report.id" class="history-item"><view class="file-icon blue">▤</view><view class="grow"><text>{{ report.name }}</text><text class="muted">{{ report.date }}</text></view><text>›</text></view></AppCard><AppCard v-if="store.state.hasUploadedReport" class="success-card"><text class="tag">解析成功</text><text class="success-text">已生成基础健康结果</text><PrimaryButton label="查看健康结果" @tap="go" /></AppCard><BottomNav active="health" /></view></template>
